package com.taskflow.service;
import com.taskflow.dto.ApiDtos.*;import com.taskflow.entity.*;import com.taskflow.exception.*;import com.taskflow.repository.EmployeeRepository;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.crypto.password.PasswordEncoder;import java.util.*;
@Service public class EmployeeService {
 private final EmployeeRepository repo;private final PasswordEncoder encoder;public EmployeeService(EmployeeRepository r,PasswordEncoder p){repo=r;encoder=p;}
 @Transactional(readOnly=true) public PageView<EmployeeView> list(String search,int page,int size){Pageable p=PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt"));return page(repo.searchActive(blank(search),p));}
 @Transactional(readOnly=true) public EmployeeView get(long id){return view(repo.findById(id).filter(e->e.getRole()==Role.EMPLOYEE).orElseThrow(()->new NotFoundException("Employee not found")));}
 @Transactional public EmployeeView create(EmployeeCreate x){String email=x.email().trim().toLowerCase(Locale.ROOT);if(repo.existsByEmailIgnoreCase(email))throw new BadRequestException("An employee with this email already exists");return view(repo.save(new Employee(x.fullName().trim(),email,encoder.encode(x.password()),x.department().trim(),x.designation().trim(),Role.EMPLOYEE,true)));}
 @Transactional public EmployeeView update(long id,EmployeeUpdate x){Employee e=repo.findById(id).filter(employee->employee.getRole()==Role.EMPLOYEE).orElseThrow(()->new NotFoundException("Employee not found"));String email=x.email().trim().toLowerCase(Locale.ROOT);repo.findByEmailIgnoreCase(email).filter(other->!other.getId().equals(id)).ifPresent(other->{throw new BadRequestException("An employee with this email already exists");});e.setFullName(x.fullName().trim());e.setEmail(email);e.setDepartment(x.department().trim());e.setDesignation(x.designation().trim());e.setActive(x.active());if(x.password()!=null&&!x.password().isBlank())e.setPasswordHash(encoder.encode(x.password()));return view(e);}
 @Transactional public void deactivate(long id){Employee e=repo.findById(id).filter(employee->employee.getRole()==Role.EMPLOYEE).orElseThrow(()->new NotFoundException("Employee not found"));e.setActive(false);}
 public static EmployeeView view(Employee e){return new EmployeeView(e.getId(),e.getFullName(),e.getEmail(),e.getDepartment(),e.getDesignation(),e.getRole(),e.isActive(),e.getCreatedAt());}
 private PageView<EmployeeView> page(Page<Employee> p){return new PageView<>(p.getContent().stream().map(EmployeeService::view).toList(),p.getTotalElements(),p.getTotalPages(),p.getNumber(),p.getSize());}
 private String blank(String s){return s==null||s.isBlank()?null:s.trim();}
}
